export const useUser = routeLoader$((requestEvent): User | null => {
  const user = getSessionUser(requestEvent);
  if (!user) {
    return null;
  }
  if (user.role !== "ADMIN" && user.role !== "USER") {
    return null;
  }
  return user;
});

export default component$(() => {
  const userSignal = useUser();

  if (userSignal.value === null) {
    // In a routeLoader$, we can't redirect. Instead, the response
    // will show an unauthorized message. We'll let the client-side
    // handle this with a redirect via the response.
    return (
      <div>
        <h1>Access Denied</h1>
        <p>You must be logged in to view this page.</p>
      </div>
    );
  }

  const user = userSignal.value;

  return (
    <div>
      <h1>Profile</h1>
      <p>
        <strong>Name:</strong> {user.name}
      </p>
      <p>
        <strong>Email:</strong> {user.email}
      </p>
      <p>
        <strong>Role:</strong> {user.role}
      </p>
    </div>
  );
});

